import styled from "styled-components";

export const PropertySiteContainer= styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 2rem;
    position: relative;

 
    
    
`

export const CardImage= styled.div`
    width:100%;
    height: 4rem;
    border-radius:2px;
  
    img{
        width: 100%;
        height: 100%;
        object-fit: cover;
    }
`
